CREATE TABLE public.checkout_policy_acceptances (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mfn_id text NOT NULL UNIQUE DEFAULT ('MFN-AC-'||upper(replace(gen_random_uuid()::text,'-',''))), person_id uuid NOT NULL, workspace_id uuid REFERENCES public.workspaces(id), reference_type text NOT NULL CHECK(reference_type IN ('customer_invoice','facility_invoice','referral_funding','membership','network_addon','combined_cart','training','test')), reference_id text NOT NULL, invoice_id uuid REFERENCES public.trip_invoice_documents(id), terms_version text NOT NULL, refund_version text NOT NULL, provider_policy_snapshot jsonb, amount_cents bigint NOT NULL CHECK(amount_cents>=0), currency text NOT NULL CHECK(currency='usd'), review_snapshot jsonb NOT NULL, attribution_hash text NOT NULL, checkout_key uuid NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.checkout_policy_acceptances TO authenticated; GRANT ALL ON public.checkout_policy_acceptances TO service_role;
ALTER TABLE public.checkout_policy_acceptances ENABLE ROW LEVEL SECURITY;
CREATE POLICY acceptance_master_read ON public.checkout_policy_acceptances FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TRIGGER acceptance_immutable BEFORE UPDATE OR DELETE ON public.checkout_policy_acceptances FOR EACH ROW EXECUTE FUNCTION public.invoice_event_immutable_guard();
COMMENT ON TABLE public.checkout_policy_acceptances IS 'Single purchase clickwrap evidence store; signup/HIPAA acknowledgments remain separate. Restricted server writes; no card credentials, no retroactive version updates.';
ALTER TABLE public.trip_payments ADD COLUMN policy_acceptance_id uuid REFERENCES public.checkout_policy_acceptances(id), ADD COLUMN charge_type text CHECK(charge_type IN ('direct','destination','separate_charge_transfer')), ADD COLUMN application_fee_ref text, ADD COLUMN reversal_evidence jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.network_payment_attempts ADD COLUMN policy_acceptance_id uuid REFERENCES public.checkout_policy_acceptances(id), ADD COLUMN charge_type text CHECK(charge_type IN ('direct','destination','separate_charge_transfer')), ADD COLUMN application_fee_ref text;
ALTER TABLE public.subscriptions ADD COLUMN initial_policy_acceptance_id uuid REFERENCES public.checkout_policy_acceptances(id);
ALTER TABLE public.course_enrollments ADD COLUMN policy_acceptance_id uuid REFERENCES public.checkout_policy_acceptances(id);
ALTER TABLE public.fin_admin_actions ADD COLUMN policy_acceptance_id uuid REFERENCES public.checkout_policy_acceptances(id), ADD COLUMN responsibility_evidence jsonb;
COMMENT ON COLUMN public.fin_admin_actions.responsibility_evidence IS 'Refund/reversal cause-review events only, not a payment ledger. Includes original charge/payment/transfer/application fee refs, principal, unreturned processor fees, application fee retained/refunded/recovered, transfer reversal, responsible party/reason/recovery state, policy versions and charge type. No automatic charging.';
CREATE FUNCTION public.refund_review_evidence_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' AND OLD.responsibility_evidence IS NOT NULL THEN RAISE EXCEPTION 'Review evidence is immutable'; END IF; IF TG_OP='UPDATE' AND OLD.responsibility_evidence IS NOT NULL THEN RAISE EXCEPTION 'Review evidence is immutable'; END IF; IF TG_OP='INSERT' AND NEW.responsibility_evidence IS NOT NULL THEN IF current_user NOT IN ('postgres','service_role','supabase_admin') OR NEW.policy_acceptance_id IS NULL OR jsonb_typeof(NEW.responsibility_evidence)<>'object' THEN RAISE EXCEPTION 'Verified server responsibility evidence required'; END IF; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
CREATE TRIGGER refund_review_history_immutable BEFORE INSERT OR UPDATE OR DELETE ON public.fin_admin_actions FOR EACH ROW EXECUTE FUNCTION public.refund_review_evidence_guard();
CREATE TABLE public.trip_invoice_access_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL REFERENCES public.trip_invoice_documents(id),token_hash text NOT NULL UNIQUE,scope text NOT NULL CHECK(scope IN ('view','payment')),expires_at timestamptz NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
GRANT ALL ON public.trip_invoice_access_tokens TO service_role;
ALTER TABLE public.trip_invoice_access_tokens ENABLE ROW LEVEL SECURITY;
COMMENT ON TABLE public.trip_invoice_access_tokens IS 'Hash-only expiring reusable view / payment-review bearer tokens; payment action still requires consent, approved fees and OFF collection flags. Tokens never contain patient IDs or card credentials.';
CREATE TABLE public.provider_facility_agreement_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),connection_id uuid NOT NULL REFERENCES public.account_business_connections(id),provider_workspace_id uuid NOT NULL REFERENCES public.workspaces(id),facility_workspace_id uuid NOT NULL REFERENCES public.workspaces(id),version integer NOT NULL CHECK(version>0),quote_reference text NOT NULL,approved_total_cents bigint NOT NULL CHECK(approved_total_cents>=0),currency text NOT NULL DEFAULT 'usd' CHECK(currency='usd'),bill_to_workspace_id uuid NOT NULL REFERENCES public.workspaces(id),responsible_payer_workspace_id uuid NOT NULL REFERENCES public.workspaces(id),provider_policy_snapshot text NOT NULL,provider_confirmed_by uuid NOT NULL,facility_confirmed_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(connection_id,version));
GRANT SELECT ON public.provider_facility_agreement_versions TO authenticated; GRANT ALL ON public.provider_facility_agreement_versions TO service_role;
ALTER TABLE public.provider_facility_agreement_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY agreement_party_read ON public.provider_facility_agreement_versions FOR SELECT TO authenticated USING(public.can_manage_account_connections(provider_workspace_id) OR public.can_manage_account_connections(facility_workspace_id));
CREATE TRIGGER agreement_version_immutable BEFORE UPDATE OR DELETE ON public.provider_facility_agreement_versions FOR EACH ROW EXECUTE FUNCTION public.invoice_event_immutable_guard();
COMMENT ON TABLE public.provider_facility_agreement_versions IS 'Explicit bilateral agreement references only; no private provider rate-table copy, browser inserts or inferred acceptance. Approved quote scope must be validated server-side before use.';
ALTER TABLE public.trip_invoice_documents ADD COLUMN facility_agreement_id uuid REFERENCES public.provider_facility_agreement_versions(id), ADD COLUMN responsible_payer_workspace_id uuid REFERENCES public.workspaces(id);
ALTER TABLE public.trip_distributions ADD COLUMN funding_versions jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN funding_required boolean NOT NULL DEFAULT false;
CREATE FUNCTION public.funding_version_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND (NEW.funding_versions<>'[]'::jsonb OR NEW.funding_required) AND current_user NOT IN ('postgres','service_role','supabase_admin') THEN RAISE EXCEPTION 'Funding is server managed'; END IF; IF TG_OP='UPDATE' AND (NEW.funding_versions IS DISTINCT FROM OLD.funding_versions OR NEW.funding_required IS DISTINCT FROM OLD.funding_required) THEN IF current_user NOT IN ('postgres','service_role','supabase_admin') OR jsonb_array_length(NEW.funding_versions)<jsonb_array_length(OLD.funding_versions) OR (SELECT coalesce(jsonb_agg(v ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(NEW.funding_versions) WITH ORDINALITY a(v,ord) WHERE ord<=jsonb_array_length(OLD.funding_versions)) IS DISTINCT FROM OLD.funding_versions THEN RAISE EXCEPTION 'Funding versions are immutable server evidence'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER funding_versions_immutable BEFORE INSERT OR UPDATE ON public.trip_distributions FOR EACH ROW EXECUTE FUNCTION public.funding_version_guard();
CREATE FUNCTION public.funding_wave_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.trip_distributions d WHERE d.id=NEW.distribution_id AND d.funding_required AND NOT EXISTS(SELECT 1 FROM public.network_settlements s JOIN public.network_payment_attempts a ON a.settlement_id=s.id WHERE s.distribution_id=d.id AND a.status='succeeded' AND a.confirmed_at IS NOT NULL AND a.policy_acceptance_id IS NOT NULL)) THEN RAISE EXCEPTION 'Verified funding required before distribution'; END IF; RETURN NEW; END $$;
CREATE TRIGGER funding_required_before_wave BEFORE INSERT ON public.trip_distribution_waves FOR EACH ROW EXECUTE FUNCTION public.funding_wave_guard();
CREATE FUNCTION public.invoice_viewed(_invoice uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.trip_invoice_access(_invoice,false) THEN RAISE EXCEPTION 'Invoice unavailable'; END IF; IF NOT EXISTS(SELECT 1 FROM public.trip_invoice_events WHERE invoice_id=_invoice AND actor_id=auth.uid() AND action='invoice_viewed') THEN INSERT INTO public.trip_invoice_events(invoice_id,action,actor_id,person_mfn_id) VALUES(_invoice,'invoice_viewed',auth.uid(),(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid())); END IF; END $$;
REVOKE ALL ON FUNCTION public.invoice_viewed(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.invoice_viewed(uuid) TO authenticated;
CREATE FUNCTION public.provider_owned_request_source() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.submitted_via='portal' AND NEW.selected_provider_workspace_id IS NULL AND NOT NEW.is_test AND EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE w.id=NEW.workspace_id AND w.account_type='provider' AND w.status='active' AND NOT w.is_test_account AND m.user_id=NEW.actor_user_id AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL) THEN NEW.intake_source:='provider_owned_operation'; END IF; RETURN NEW; END $$;
CREATE TRIGGER zzz_provider_owned_source BEFORE INSERT ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.provider_owned_request_source();